import { Check, Coffee, Moon } from "lucide-react";

import { studyDayLabels } from "../constants/study-days.constants";
import { studyDays, type StudyDay } from "../types/onboarding.types";
import { cn } from "@/lib/utils";

type StudyDaysCalendarProps = {
  selectedDays: StudyDay[];
  dailyMinutes: number;
  disabled: boolean;
  onToggle: (day: StudyDay) => void;
};

export function StudyDaysCalendar({ selectedDays, dailyMinutes, disabled, onToggle }: StudyDaysCalendarProps) {
  return (
    <div role="group" aria-label="Dias disponíveis para estudar" className="grid grid-cols-2 gap-3 sm:grid-cols-4 lg:grid-cols-7">
      {studyDays.map((day) => {
        const selected = selectedDays.includes(day);
        const Icon = selected ? Check : day === "DOM" ? Coffee : Moon;
        return (
          <button key={day} type="button" disabled={disabled} aria-pressed={selected}
            aria-label={studyDayLabels[day]} onClick={() => onToggle(day)}
            className={cn("flex min-h-32 flex-col items-center justify-center gap-3 rounded-xl px-3 py-5 text-xs transition-colors focus-visible:outline-2 focus-visible:outline-offset-4 focus-visible:outline-blue-600 disabled:opacity-60",
              selected ? "bg-[#0733a5] text-white hover:bg-[#052b8c]" : "bg-[#edefff] text-[#6d738b] hover:bg-[#dfe4ff]")}>
            <span className="font-semibold tracking-wide">{day === "SAB" ? "SÁB" : day}</span>
            <span className={cn("flex size-10 items-center justify-center rounded-full", selected ? "bg-white/15" : "bg-white/50")}>
              <Icon className="size-5" aria-hidden="true" />
            </span>
            <span>{selected ? (dailyMinutes % 60 === 0 ? dailyMinutes / 60 + "h ativa" : dailyMinutes + " min") : day === "DOM" ? "Descanso" : "Pausa"}</span>
          </button>
        );
      })}
    </div>
  );
}
