"use client";

import { useEffect, useState } from "react";
import { useRouter } from "next/navigation";

import { recommendedStudyDays } from "../constants/study-days.constants";
import { studyDaysSchema } from "../schemas/study-days.schema";
import { onboardingStorage } from "../storage/onboarding.storage";
import { studyDays, type StudyDay } from "../types/onboarding.types";

export function useStudyDays() {
  const router = useRouter();
  const [selectedDays, setSelectedDays] = useState<StudyDay[]>(recommendedStudyDays);
  const [dailyMinutes, setDailyMinutes] = useState(120);
  const [error, setError] = useState<string | null>(null);
  const [ready, setReady] = useState(false);

  useEffect(() => {
    const draft = onboardingStorage.getDraft();
    // Restore the existing onboarding draft only after hydration.
    // eslint-disable-next-line react-hooks/set-state-in-effect
    setSelectedDays(draft.studyDays.length ? draft.studyDays : recommendedStudyDays);
    setDailyMinutes(Number(draft.dailyMinutes ?? 120));
    setReady(true);
  }, []);

  function toggleDay(day: StudyDay) {
    setError(null);
    setSelectedDays((current) => studyDays.filter((item) =>
      item === day ? !current.includes(item) : current.includes(item),
    ));
  }

  function selectWeekdays() {
    setError(null);
    setSelectedDays([...recommendedStudyDays]);
  }

  function handleContinue() {
    const result = studyDaysSchema.safeParse({ studyDays: selectedDays });
    if (!result.success) {
      setError(result.error.issues[0]?.message ?? "Selecione um dia.");
      return;
    }
    try {
      onboardingStorage.saveStudyDays(result.data.studyDays);
      router.push("/onboarding/tempo");
    } catch {
      setError("Não foi possível salvar sua rotina. Tente novamente.");
    }
  }

  return { selectedDays, dailyMinutes, error, ready, toggleDay, selectWeekdays, handleContinue };
}
